head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gEmpNm = js_emp_nm;
scwin.gLdMktTp = js_market;
scwin.gNOTI_SVC_ID;
scwin.vScrenID = "ULDSTF30375.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.fn_SetCode_1();
    scwin.fn_SetCode_2();
};
scwin.fn_SetCode_1 = function() {
    $c.stf.setObjectValue(txb_EMP_NO, scwin.gEmpNo);
    $c.stf.setObjectValue(txb_dep_cd, scwin.gDepCd);
    $c.stf.setObjectValue(txb_fromName, scwin.gEmpNm);
};
scwin.fn_SetCode_2 = function() {
    $c.stf.setObjectValue(txb_fromCellNo, "02-3774-9000");
};
scwin.fn_getListSmsTp = function() {
    dts_Msg.DataID = "/NoteMgt.do?method=listExturePlusMbrSmsTp" + "&LD_MKT_TP_CD=" + scwin.gLdMktTp + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=C";

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Msg.Reset();
};
scwin.fn_SetHeader = function() {
    dts_Master.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_EMAIL_SMS_RECEIVER_INOUT";

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Master.Reset();

	//----W-Craft WebSquare 변환 확인: AddRow----//
    dts_Master.AddRow();
    scwin.fn_SetHeaderRcvr();
};
scwin.fn_SetHeaderRcvr = function() {
    dts_Receiver.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MBR_EM_CONTACT_INFO_INOUT";

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Receiver.Reset();
};
scwin.initPage = function() {
    var ToDay = $c.ut.cGetToday2();
    $c.stf.setObjectValue(edt_EDATE, ToDay);
    var vSDATE = $c.ut.calcMonth(ToDay, -6);
    $c.stf.setObjectValue(edt_SDATE, vSDATE);
    scwin.fn_getListSmsTp();
};
scwin.fn_readSendSMS = function(row, colid) {
    if (colid == "CONTN") {

	//----W-Craft WebSquare 변환 확인: NameString----//
        scwin.gNOTI_SVC_ID = dts_Grid.NameString(row, "NOTI_SVC_ID");
        var url = "/NoteMgt.do?method=listSendExturePlusMbrInfo" + "&MDTYPE=E" + "&SDATE=" + $c.stf.getObjectValue(edt_SDATE) + "&EDATE=" + $c.stf.getObjectValue(edt_EDATE) + "&DEP_CD=" + scwin.gDepCd + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Master.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
        dts_Master.Reset();

        //alert(dts_Master.NameString(row, "SND_CHRG_EMP_NM") + "\n" + dts_Master.NameString(row, "SND_NO"));

        var urlReceiver = "/NoteMgt.do?method=listRcvExturePlusMbr" + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Receiver.DataID = encodeURI(urlReceiver);

	//----W-Craft WebSquare 변환 확인: Reset----//
        dts_Receiver.Reset();
    }
};
scwin.fn_Search = function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return;
    }
    var url = "/NoteMgt.do?method=listSendExturePlusMbrInfo";
    url += "&MDTYPE=E"; //EXTURE 회원사 SMS알림:E
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&NOTI_SVC_ID=";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_RowCount = function() {
    $c.stf.setObjectValue(txb_receiver_cnt, "총 : " + dts_Receiver.CountRow + " 건");
};
scwin.fn_SmsTpSelect = function() {

	//----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    var vSelectedVal = cmb_SmsTp.ValueOfIndex("VALUE", cmb_SmsTp.Index);
    txa_CONTN.setValue(vSelectedVal);
};
scwin.fn_registerSMS = function() {
    if (scwin.fn_CheckForm()) {
        var msg = $c.stf.getMessageParam("MSG-A006", "전송");
        scwin.fn_SetCode_1(); //보내는 사람,이름,부서 고정

        if (window.confirm(msg)) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
            var url = "/SmsMgt.do?method=registerSmsSendToExturePlusMbr" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02; /*ORG SRC: dts_Master.NameString(1, "TITLE") = getObjectText(cmb_SmsTp);*/ X = $c.stf.getObjectText(cmb_SmsTp);
            /*

	//----W-Craft WebSquare 변환 확인: NameString----//
            alert(dts_Master.NameString(1, "SND_CHRG_EMP_NO")

	//----W-Craft WebSquare 변환 확인: NameString----//
              + "\n" + dts_Master.NameString(1, "SND_NO")

	//----W-Craft WebSquare 변환 확인: NameString----//
              + "\n" + dts_Master.NameString(1, "DEP_CD")

	//----W-Craft WebSquare 변환 확인: NameString----//
              + "\n" + dts_Master.NameString(1, "TITLE"));
            */
            for (var i = 1; i <= dts_Receiver.CountRow; i++) {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
                /*ORG SRC: dts_Receiver.NameString(i, "EMP_NO") = gEmpNo; //수정상태로 변경*/
                X = scwin.gEmpNo; //수정상태로 변경

            }
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver)";

	//----W-Craft WebSquare 변환 확인: post----//
            trs_Save.post();
        }
    }
};
$c.en.fn_CheckForm = function() {
    var msg = "";
    if ($c.stf.getObjectValue(txa_CONTN) == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "보내는 내용");
        alert(msg);

	//----W-Craft WebSquare 변환 확인: Focus----//
        txa_CONTN.Focus();
        return false;
    }
    //setObjectValue(txb_title_size, getStringSize(getObjectValue(txa_CONTN)));

    if ($c.stf.getStringSize($c.stf.getObjectValue(txa_CONTN)) > 2000) {
        alert('보내는내용이 2000Byte가 초과되었습니다.');

	//----W-Craft WebSquare 변환 확인: Focus----//
        txa_CONTN.Focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_fromCellNo) == "" || $c.stf.getObjectValue(txb_fromCellNo) == "-") {
        msg = $c.stf.getMessageParam("MSG-A005", "보내는 번호");
        alert(msg);

	//----W-Craft WebSquare 변환 확인: focus----//
        txb_fromCellNo.focus();
        return false;
    }
    if (!$c.stockSearch.isNumber($c.stf.getObjectValue(txb_fromCellNo))) {
        alert("[보내는 번호]를 숫자로 입력해주세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        txb_fromCellNo.focus();
        return;
    }
    if (dts_Receiver.CountRow == 0) {
        alert("선택된 수신자가 없습니다.");
        return false;
    }

    //휴대폰번호 확인
    var regExpCell = /^01(?:0|1|[6-9])(?:\d{4})\d{4}$/; //정규식 체크 - 휴대폰번호
    var cellphoneNo = "";
    for (var i = 1; i <= dts_Receiver.CountRow; i++) {

	//----W-Craft WebSquare 변환 확인: NameString----//
        cellphoneNo = (dts_Receiver.NameString(i, "CELLPHONE_NO")).replace(/-/g, "");
        if (!regExpCell.test(cellphoneNo)) {
            alert("[휴대전화번호]를 확인해 주세요.");
            dts_Receiver.RowPosition = i;

	//----W-Craft WebSquare 변환 확인: SetColumn----//
            grd_Receiver.SetColumn("CELLPHONE_NO");

	//----W-Craft WebSquare 변환 확인: focus----//
            grd_Receiver.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_New = function() {
    scwin.fn_SetCode();
    scwin.fn_SetHeaderRcvr();
};

	//----W-Craft WebSquare 변환 확인: addRow----//

	//----W-Craft WebSquare 변환 확인: focus----//
scwin.fn_addRow = function(bnd, grid, column_nm, focus_yn) {

	//----W-Craft WebSquare 변환 확인: addRow----//
    bnd.addRow();

	//----W-Craft WebSquare 변환 확인: focus----//
    if (focus_yn != "N") {

	//----W-Craft WebSquare 변환 확인: SetColumn----//
        grid.SetColumn(column_nm);

	//----W-Craft WebSquare 변환 확인: Focus----//
        grid.Focus();
    }
};
scwin.fn_deleteRow = function(bnd, grid) {

	//----W-Craft WebSquare 변환 확인: deleterow----//
    bnd.deleterow(bnd.rowposition);

	//----W-Craft WebSquare 변환 확인: Focus----//
    grid.Focus();
};
scwin.fn_AddRcvOper = function() {
    scwin.fn_SearchRcvOper();
};
scwin.fn_SearchRcvOper = function() {
    var url = "/NoteMgt.do?method=listRcvObjMktOper";
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Oper.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Oper.Reset();
};

	//----W-Craft WebSquare 변환 확인: addRow----//
scwin.fn_addRowFromRcvOper = function() {
    grd_Receiver.Redraw = false;
    var j = 1 + dts_Receiver.CountRow;
    for (var i = 1; i <= dts_Oper.CountRow; i++) {

	//----W-Craft WebSquare 변환 확인: NameString----//
        var vLength = dts_Oper.NameString(i, "CELLPHONE_NO").length;
        if (vLength > 0) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//

	//----W-Craft WebSquare 변환 확인: AddRow----//
            dts_Receiver.AddRow(); /*ORG SRC: dts_Receiver.NameString(j, "EXTUREPLUS_MBR_ID") = dts_Oper.NameString(i, "EXTUREPLUS_MBR_ID");*/ X = dts_Oper.NameString(i, "EXTUREPLUS_MBR_ID"); /*ORG SRC: dts_Receiver.NameString(j, "EXTUREPLUS_MBR_NM") = dts_Oper.NameString(i, "EXTUREPLUS_MBR_NM");*/ X = dts_Oper.NameString(i, "EXTUREPLUS_MBR_NM"); /*ORG SRC: dts_Receiver.NameString(j, "DEP_NM") = dts_Oper.NameString(i, "DEP_NM");*/ X = dts_Oper.NameString(i, "DEP_NM"); /*ORG SRC: dts_Receiver.NameString(j, "CHRG_NM") = dts_Oper.NameString(i, "CHRG_NM");*/ X = dts_Oper.NameString(i, "CHRG_NM"); /*ORG SRC: dts_Receiver.NameString(j, "JOBTITL_NM") = dts_Oper.NameString(i, "JOBTITL_NM");*/ X = dts_Oper.NameString(i, "JOBTITL_NM"); /*ORG SRC: dts_Receiver.NameString(j, "TEL_NO") = dts_Oper.NameString(i, "TEL_NO");*/ X = dts_Oper.NameString(i, "TEL_NO"); /*ORG SRC: dts_Receiver.NameString(j, "CELLPHONE_NO") = dts_Oper.NameString(i, "CELLPHONE_NO");*/ X = dts_Oper.NameString(i, "CELLPHONE_NO");
            j++;
        }
    }
    grd_Receiver.Redraw = true;
    scwin.fn_RowCount();
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.btn_SDATE_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function(info) {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.btn_Search_onclick = function(e) {
    scwin.fn_Search();
};
scwin.dts_Receiver_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(txb_receiver_cnt, "총 : " + rowcount + " 건");
};
scwin.dts_Master_OnLoadCompleted = function(rowcount) {

};
scwin.dts_Oper_OnLoadCompleted = function(rowcount) {

	//----W-Craft WebSquare 변환 확인: addRow----//
    scwin.fn_addRowFromRcvOper();
};
scwin.txa_CONTN_OnChange = function(info) {
    $c.stf.setObjectValue(txb_title_size, $c.stf.getStringSize($c.stf.getObjectValue(txa_CONTN)));
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    if (dts_Grid.errorMsg) {
        alert("OnLoadCompleted Error => " + dts_Grid.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    if (colid == "CONTN") {
        scwin.fn_readSendSMS(row, colid);
    }
};
scwin.trs_Save_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-A002", "전송");
    alert(msg);
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    var msg = $c.stf.getMessageParam("MSG-A001", "전송");
    alert(msg);
    scwin.fn_Search();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.libRoundPanel.PanelToGroupBox(panel_2);
    scwin.initPage();
    scwin.fn_Search();
    scwin.fn_SetHeader();
    scwin.fn_SetCode();
};
scwin.cmb_SmsTp_OnSelChange = function(info) {
    scwin.fn_SmsTpSelect();
};
scwin.img_send_onclick = function(e) {
    scwin.fn_registerSMS();
};
scwin.img_srch_onclick = function(e) {
    var send_url = "/bizspt/ULDSTF30376.gfm";

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    frame.CreateDialogFrame("RECEIVER_FOR_MAIL", send_url, "수신자 선택", 10, 10, 893, 550, "window");
};
scwin.btn_sub1_lineadd_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: addRow----//
    scwin.fn_addRow(dts_Receiver, grd_Receiver, "CHRG_NM");
    scwin.fn_RowCount();
};
scwin.btn_sub1_linedelete_onclick = function(e) {
    scwin.fn_deleteRow(dts_Receiver, grd_Receiver);
    scwin.fn_RowCount();
};
scwin.btn_Oper_onclick = function(e) {
    scwin.fn_AddRcvOper();
};
scwin.btn_Init_onclick = function(e) {
    scwin.fn_New();
};
